import pytest


def daily_returns(prices):
    # simple returns; a price of zero or less is an error
    if any(p <= 0 for p in prices):
        raise ValueError("prices must be positive")
    return [b / a - 1 for a, b in zip(prices, prices[1:])]


@pytest.mark.parametrize("prices, expected", [
    ([100.00, 110.00, 99.00], [0.1, -0.1]),
    ([50.00, 50.00], [0.0]),
    ([80.00], []),
])
def test_returns_by_hand(prices, expected):
    assert daily_returns(prices) == pytest.approx(expected)


def test_bad_price_raises():
    with pytest.raises(ValueError):
        daily_returns([100.00, 0.00, 105.00])

